import { mkdir, copyFile, rm } from "node:fs/promises";
import { fileURLToPath } from "node:url";
const root = fileURLToPath(new URL("../", import.meta.url));
// public/ is exclusively generated by this script; clear obsolete dependency assets.
await rm(`${root}public`, { recursive: true, force: true });
await mkdir(`${root}public/fonts`, { recursive: true });
await mkdir(`${root}public/licenses`, { recursive: true });
for (const weight of [400, 700]) {
  for (const style of ["normal", "italic"]) {
    const target = `Lato-${weight}${style === "italic" ? "-italic" : ""}.woff2`;
    await copyFile(
      `${root}node_modules/@fontsource/lato/files/lato-latin-${weight}-${style}.woff2`,
      `${root}public/fonts/${target}`,
    );
  }
}
await copyFile(
  `${root}node_modules/@brightspace-ui/core/LICENSE`,
  `${root}public/licenses/Brightspace-APACHE-2.0.txt`,
);
await copyFile(
  `${root}node_modules/@brightspace-ui/intl/LICENSE`,
  `${root}public/licenses/Brightspace-Intl-APACHE-2.0.txt`,
);
await copyFile(
  `${root}node_modules/@fontsource/lato/LICENSE`,
  `${root}public/licenses/Lato-OFL.txt`,
);
